// The five skill packs (track AM-10129, Phase 3): Markdown-only plugins built from the root `skills/` folder by scripts/build-skill-packs.mjs,
// hooked into scripts/build-plugin.mjs. The drift check (first test of plugin-build.test.mjs) already compares every generated byte with
// disk; these tests check what the packs promise: each skill in exactly one pack, the copy is byte-identical, nothing but advice and
// templates ships, the README names its skills, the marketplace lists all eight plugins, the base is untouched, and the generator refuses a
// pack list that does not match skills/. The skills library checks (checker, privacy gate) run when skills-tools has its dependencies.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { REPO, buildAll, buildPlugin, MARKETPLACE_REL, RELS, pluginVersion } from '../../scripts/build-plugin.mjs';
import { buildSkillPacks, readPacks, skillFolders, skillDescription, PACKS_REL } from '../../scripts/build-skill-packs.mjs';

const SPEC_TABLE = {
  'laneconductor-nodejs-frontend': ['pwa-vite-workbox', 'browser-tts-unlock-voice-binding'],
  'laneconductor-firebase': ['shared-gcp-firebase-site', 'cache-buster', 'firebase-google-sign-in'],
  'laneconductor-node-postgres': ['postgres-local-neon-prod-secret-manager', 'prisma-in-cloud-functions', 'isolated-test-database', 'makefile-local-run'],
  'laneconductor-gemini': ['llm-through-tokentalos', 'vertex-gemini-adc', 'vertex-imagen-retry-gcs-fallback'],
  'laneconductor-skill-from-code': ['plugin-from-skills', 'skill-from-code'],
};
// A claim of being listed in Anthropic's directory is forbidden until a reviewer has published the plugin (track AM-10148); a plain mention
// (for example a skill that helps to submit one) is fine.
const claimsListing = (t) => /\b(listed|available|published|live)\b[^.\n]{0,30}\bdirectory\b/i.test(t) || /\bdirectory\b[^.\n]{0,30}\b(listing|listed)\b/i.test(t);
const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const listFiles = (root, rel = '') => fs.readdirSync(path.join(root, rel), { withFileTypes: true }).flatMap((e) => {
  const r = rel ? `${rel}/${e.name}` : e.name;
  return e.isDirectory() ? listFiles(root, r) : [r];
});
const packs = readPacks(REPO);
const dirOf = (pack) => path.join(REPO, 'plugins', pack.name);
const words = (t) => t.replace(/```[\s\S]*?```/g, ' ').split(/\s+/).filter((w) => /[A-Za-z0-9]/.test(w)).length;

test('the pack list is exactly the five packs of the spec, and every skill folder is in exactly one of them', () => {
  assert.deepEqual(Object.fromEntries(packs.map((p) => [p.name, p.skills])), SPEC_TABLE);
  const all = packs.flatMap((p) => p.skills);
  assert.equal(new Set(all).size, all.length, 'no skill twice');
  assert.deepEqual([...all].sort(), skillFolders(REPO), 'every folder under skills/ is in a pack, and every pack skill exists');
  assert.equal(skillFolders(REPO).length, 14);
  // Each pack has its own version, independent of the other plugins and of each other (a pack moves when its skills change).
  for (const p of packs) assert.match(p.version, /^\d+\.\d+\.\d+$/, `${p.name}: its own semver version`);
});

test('each pack folder holds exactly the files of its skills, byte for byte (hidden template files included), and nothing else but the fixed parts', () => {
  for (const p of packs) {
    const dir = dirOf(p);
    const expected = [
      '.claude-plugin/icon.png', '.claude-plugin/plugin.json', 'LICENSE', 'README.md',
      ...p.skills.flatMap((s) => listFiles(path.join(REPO, 'skills', s)).map((r) => `skills/${s}/${r}`)),
    ].sort();
    assert.deepEqual(listFiles(dir).sort(), expected, p.name);
    for (const s of p.skills) {
      for (const r of listFiles(path.join(REPO, 'skills', s))) {
        assert.ok(fs.readFileSync(path.join(REPO, 'skills', s, r)).equals(fs.readFileSync(path.join(dir, 'skills', s, r))), `${p.name}: skills/${s}/${r} is byte-identical to its source`);
      }
    }
    assert.ok(fs.readFileSync(path.join(REPO, 'LICENSE')).equals(fs.readFileSync(path.join(dir, 'LICENSE'))), `${p.name}: LICENSE is the repository's`);
    assert.ok(fs.readFileSync(path.join(REPO, 'connector/plugin-extras/icon.png')).equals(fs.readFileSync(path.join(dir, '.claude-plugin/icon.png'))), `${p.name}: the same icon as the other plugins`);
  }
  // The hidden template files really are there (a copy that skipped dotfiles would pass the loops above only if the source lost them too).
  assert.ok(fs.existsSync(path.join(dirOf(packs[1]), 'skills/shared-gcp-firebase-site/files/.firebaserc.tmpl')));
  assert.ok(fs.existsSync(path.join(dirOf(packs[2]), 'skills/postgres-local-neon-prod-secret-manager/files/.env.example.tmpl')));
});

test('a pack ships no script, hook, MCP server, package file, agent or isolation key, and nothing executable', () => {
  const banned = /(^|\/)(\.mcp\.json|package\.json|package-lock\.json|hooks|hooks\.json|agents|commands|server|bin)(\/|$)/;
  for (const p of packs) {
    const dir = dirOf(p);
    for (const r of listFiles(dir)) {
      assert.ok(!banned.test(r), `${p.name}: ${r} must not ship in a Markdown-only pack`);
      assert.equal(fs.statSync(path.join(dir, r)).mode & 0o111, 0, `${p.name}: ${r} is executable`);
    }
    const manifest = readJson(path.join(dir, '.claude-plugin/plugin.json'));
    for (const k of ['mcpServers', 'hooks', 'agents', 'dependencies', 'isolation', 'commands']) assert.equal(manifest[k], undefined, `${p.name}: manifest key ${k}`);
    for (const r of listFiles(dir).filter((f) => f.endsWith('SKILL.md'))) {
      const front = fs.readFileSync(path.join(dir, r), 'utf8').match(/^---\n([\s\S]*?)\n---\n/)[1];
      assert.ok(!/^isolation:/m.test(front), `${r}: isolation key`);
    }
    // The only top-level entries are the plugin manifest folder, the skills, the README and the LICENSE.
    assert.deepEqual(fs.readdirSync(dir).sort(), ['.claude-plugin', 'LICENSE', 'README.md', 'skills']);
    assert.deepEqual(fs.readdirSync(path.join(dir, '.claude-plugin')).sort(), ['icon.png', 'plugin.json']);
  }
});

test('plugin.json has the same shape as the other plugins: author, homepage, repository, license, keywords, privacyPolicyUrl', () => {
  const board = readJson(path.join(REPO, RELS.board, '.claude-plugin/plugin.json'));
  for (const p of packs) {
    const m = readJson(path.join(dirOf(p), '.claude-plugin/plugin.json'));
    assert.deepEqual(Object.keys(m), Object.keys(board), `${p.name}: same keys in the same order`);
    assert.equal(m.name, p.name);
    assert.equal(m.version, p.version);
    assert.equal(m.description, p.description);
    assert.equal(m.displayName, p.displayName);
    assert.deepEqual(m.keywords, p.keywords);
    for (const k of ['author', 'homepage', 'repository', 'license', 'privacyPolicyUrl']) assert.deepEqual(m[k], board[k], `${p.name}: ${k}`);
    assert.equal(m.license, 'Elastic-2.0');
  }
});

test('each pack README names each of its skills with its frontmatter description, has install and update lines, the advice note and the docs link, in under 400 words', () => {
  for (const p of packs) {
    const md = fs.readFileSync(path.join(dirOf(p), 'README.md'), 'utf8');
    for (const s of p.skills) {
      assert.ok(md.includes(`\`${s}\``), `${p.name}: README names ${s}`);
      const desc = skillDescription(fs.readFileSync(path.join(REPO, 'skills', s, 'SKILL.md'), 'utf8'), s);
      assert.ok(md.includes(desc), `${p.name}: README carries the description of ${s}`);
    }
    assert.ok(md.includes('claude plugin marketplace add meller/laneconductor'));
    assert.ok(md.includes(`claude plugin install ${p.name}@laneconductor`));
    assert.ok(md.includes('claude plugin marketplace update laneconductor'));
    assert.ok(md.includes(`claude plugin update ${p.name}@laneconductor`));
    assert.match(md, /one author's own conventions/);
    assert.match(md, /never orders/);
    assert.ok(md.includes('https://github.com/meller/laneconductor/blob/main/docs/skills.md'));
    assert.match(md, /Elastic License 2\.0/);
    assert.ok(!claimsListing(md), `${p.name}: no claim about Anthropic's directory`);
    assert.ok(words(md) < 400, `${p.name}: ${words(md)} words`);
  }
});

test('the marketplace lists all eight plugins: the three first, then the five packs, each pack with its own version', () => {
  const market = readJson(path.join(REPO, MARKETPLACE_REL));
  assert.deepEqual(market.plugins.map((p) => p.name), ['laneconductor', 'laneconductor-parallel', 'laneconductor-board', ...packs.map((p) => p.name)]);
  assert.equal(market.plugins.length, 8);
  for (const p of packs) {
    const e = market.plugins.find((x) => x.name === p.name);
    assert.equal(e.source, `./plugins/${p.name}`);
    assert.equal(e.version, p.version);
    assert.equal(e.version, readJson(path.join(dirOf(p), '.claude-plugin/plugin.json')).version, 'the entry and the manifest agree');
    assert.equal(e.description, p.description);
    assert.deepEqual(e.author, { name: 'Asaf Meller' });
    assert.ok(fs.existsSync(path.join(REPO, e.source, '.claude-plugin/plugin.json')));
  }
  // The three older plugins take their own version (pluginVersion: an override in versions.json, else the connector's); packs have theirs.
  for (const [profile, rel] of Object.entries(RELS)) assert.equal(readJson(path.join(REPO, rel, '.claude-plugin/plugin.json')).version, pluginVersion(profile), `${rel}: the plugin carries its own version`);
});

test('docs/plugin-map.md lists each pack with the skills it holds', () => {
  const map = fs.readFileSync(path.join(REPO, 'docs/plugin-map.md'), 'utf8');
  const section = map.slice(map.indexOf('## Skill packs'));
  assert.ok(section.length > 0 && map.includes('## Skill packs'));
  for (const p of packs) {
    const line = section.split('\n').find((l) => l.startsWith(`| \`${p.name}\` |`));
    assert.ok(line, `${p.name} has a row`);
    for (const s of p.skills) assert.ok(line.includes(`\`${s}\``), `${p.name}: ${s}`);
    assert.ok(line.includes(p.version));
  }
});

test('the root README has a Skill packs section with every pack and its install command, and claims nothing about Anthropic\'s directory', () => {
  const md = fs.readFileSync(path.join(REPO, 'README.md'), 'utf8');
  const start = md.indexOf('\n## Skill packs');
  assert.ok(start > 0, 'a "Skill packs" section');
  const section = md.slice(start + 1, md.indexOf('\n## ', start + 5) > 0 ? md.indexOf('\n## ', start + 5) : undefined);
  for (const p of packs) {
    assert.ok(section.includes(`\`${p.name}\``), `${p.name} in the table`);
    assert.ok(section.includes(`claude plugin install ${p.name}@laneconductor`), `${p.name}: install command`);
  }
  assert.ok(!claimsListing(section), 'no directory claim in the section');
});

test('the pack build never writes into the base plugin, which stays what the generator makes of its own sources', () => {
  const { files } = buildSkillPacks(REPO);
  for (const rel of files.keys()) assert.ok(!rel.startsWith('plugins/laneconductor/'), `${rel} is inside the base`);
  assert.ok(!packs.some((p) => p.name === 'laneconductor'), 'no pack is named like the base');
  const want = buildPlugin(REPO, 'base');
  const have = listFiles(path.join(REPO, RELS.base));
  assert.deepEqual([...want.keys()].sort(), have.sort(), 'the base folder holds exactly what the base build makes');
  for (const [rel, f] of want) assert.ok(f.content.equals(fs.readFileSync(path.join(REPO, RELS.base, rel))), `${rel} unchanged`);
});

test('the build is deterministic: two runs give the same bytes, in the same order', () => {
  const a = buildAll();
  const b = buildAll();
  assert.deepEqual([...a.keys()], [...b.keys()]);
  for (const [k, v] of a) assert.ok(v.content.equals(b.get(k).content), k);
  assert.ok(a.has('plugins/laneconductor-gemini/README.md'));
});

// ---- The generator refuses a pack list that does not match skills/ ----
function scratch(skills, packList) {
  const tmp = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), 'lc-packs-'));
  for (const s of skills) {
    fs.mkdirSync(path.join(tmp, 'skills', s), { recursive: true });
    fs.writeFileSync(path.join(tmp, 'skills', s, 'SKILL.md'), `---\nname: ${s}\ndescription: "Skill ${s}."\n---\nbody\n`);
  }
  fs.mkdirSync(path.join(tmp, 'scripts'), { recursive: true });
  const pack = (name, sk) => ({ name, displayName: name, version: '0.1.0', description: `Pack ${name}.`, keywords: ['x'], skills: sk });
  fs.writeFileSync(path.join(tmp, PACKS_REL), JSON.stringify({ packs: packList.map(([n, sk]) => pack(n, sk)) }));
  return tmp;
}
const cli = (repo) => spawnSync(process.execPath, [path.join(REPO, 'scripts/build-skill-packs.mjs'), '--repo', repo], { encoding: 'utf8' });

test('generator errors: a skill in no pack, a skill in two packs and a pack naming a missing skill each fail with a clear message', () => {
  const dirs = [];
  try {
    const ok = scratch(['a', 'b'], [['p-one', ['a']], ['p-two', ['b']]]);
    dirs.push(ok);
    assert.equal(readPacks(ok).length, 2, 'the scratch fixture itself is valid');
    assert.equal(cli(ok).status, 0);

    const none = scratch(['a', 'b', 'c'], [['p-one', ['a']], ['p-two', ['b']]]);
    dirs.push(none);
    assert.throws(() => readPacks(none), /the skill "c" is in no pack/);
    const r1 = cli(none);
    assert.notEqual(r1.status, 0);
    assert.match(r1.stderr, /the skill "c" is in no pack/);

    const two = scratch(['a', 'b'], [['p-one', ['a', 'b']], ['p-two', ['b']]]);
    dirs.push(two);
    assert.throws(() => readPacks(two), /the skill "b" is in 2 packs \(p-one, p-two\)/);
    const r2 = cli(two);
    assert.notEqual(r2.status, 0);
    assert.match(r2.stderr, /the skill "b" is in 2 packs/);

    const missing = scratch(['a'], [['p-one', ['a', 'ghost']]]);
    dirs.push(missing);
    assert.throws(() => readPacks(missing), /pack p-one names the skill "ghost", but skills\/ghost\/ does not exist/);
    const r3 = cli(missing);
    assert.notEqual(r3.status, 0);
    assert.match(r3.stderr, /names the skill "ghost"/);

    const bare = scratch(['a'], [['p-one', ['a']]]);
    dirs.push(bare);
    fs.mkdirSync(path.join(bare, 'skills/empty-folder'));
    assert.throws(() => readPacks(bare), /skills\/empty-folder\/ has no SKILL\.md/);
  } finally {
    for (const d of dirs) fs.rmSync(d, { recursive: true, force: true });
  }
});

// ---- The Claude CLI and the skills library tools, when they are available ----
const claudeAvailable = () => { const r = spawnSync('claude', ['--version'], { encoding: 'utf8' }); return !r.error && r.status === 0; };

for (const p of packs) {
  test(`claude plugin validate --strict passes on ${p.name}`, (t) => {
    if (!claudeAvailable()) return t.skip('the claude CLI is not on PATH: run `claude plugin validate <path> --strict` by hand');
    const r = spawnSync('claude', ['plugin', 'validate', dirOf(p), '--strict'], { encoding: 'utf8', cwd: os.tmpdir() });
    assert.equal(r.status, 0, `${r.stdout}\n${r.stderr}`);
    assert.match(r.stdout, /Validation passed/);
  });
}

test('the skills library checks still pass on skills/: the checker with no errors or warnings, the privacy gate without a deny list reports no finding', (t) => {
  if (!fs.existsSync(path.join(REPO, 'skills-tools/node_modules'))) return t.skip('skills-tools has no node_modules: run `cd skills-tools && npm ci`');
  const check = spawnSync(process.execPath, [path.join(REPO, 'skills-tools/bin/check.mjs')], { encoding: 'utf8', cwd: REPO });
  assert.equal(check.status, 0, `${check.stdout}\n${check.stderr}`);
  assert.doesNotMatch(check.stdout, /\b(error|warning)\b.*[1-9]/i);
  // The owner's private deny list is not in the repository, so this run checks patterns only (secrets, emails, paths, URLs, hashes).
  const gate = spawnSync(process.execPath, [path.join(REPO, 'skills-tools/bin/gate.mjs'), '--no-deny-list'], { encoding: 'utf8', cwd: REPO });
  assert.equal(gate.status, 0, `${gate.stdout}\n${gate.stderr}`);
});

test('the directory guard still catches a real listing claim and allows a plain mention', () => {
  for (const bad of ['It is listed in Anthropic\'s plugin directory.', 'Now available in the Anthropic directory', 'Install it from the directory listing', 'Live in Anthropic\'s directory']) assert.ok(claimsListing(bad), bad);
  for (const ok of ['Packages your skills as a plugin and walks the submission to Anthropic\'s plugin directory.', 'ready for Anthropic\'s directory', 'A skill that helps submit a plugin to the plugin directory']) assert.ok(!claimsListing(ok), ok);
});
